input.sparql:
SELECT ?power_id ?occupancy_id WHERE {
  ?zn a brick:HVAC_Zone ;
    rdfs:label "DataCenter_top_ZN_6" ;
    brick:hasPoint ?occupancy, ?power .
  ?occupancy ref:hasTimeseriesId ?occupancy_id ; a brick:Occupancy_Sensor .
  ?power ref:hasTimeseriesId ?power_id ; a brick:Electric_Power_Sensor .
}
